from datetime import timedelta


def _holiday_set(holidays):
    # Copy into a set so the caller's collection is never modified or consumed twice.
    return set(holidays)


def _is_workday(day, holiday_set):
    return day.weekday() < 5 and day not in holiday_set


def add_workdays(start, days, holidays=()):
    """The date `days` working days from `start`. See TASK.md."""
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("days must be an int")
    hs = _holiday_set(holidays)
    if days == 0:
        day = start
        while not _is_workday(day, hs):
            day += timedelta(days=1)
        return day
    step = timedelta(days=1 if days > 0 else -1)
    remaining = abs(days)
    day = start
    while remaining:
        day += step
        if _is_workday(day, hs):
            remaining -= 1
    return day


def count_workdays(first, last, holidays=()):
    """Working days from `first` to `last`, both included. See TASK.md."""
    if first > last:
        return -count_workdays(last, first, holidays)
    hs = _holiday_set(holidays)
    count = 0
    day = first
    while day <= last:
        if _is_workday(day, hs):
            count += 1
        day += timedelta(days=1)
    return count
